// Branch Manager decisions authorize one cashier password change through Supabase Auth.
async function loadCashierPasswordRequests(){S.passwordRequests=[];S.passwordRequestsReady=false;S.passwordRequestsError='';if(!['BC','BM','DM','Admin'].includes(S.role))return;try{S.passwordRequests=await allRows('/rest/v1/occci_password_requests?select=*&order=created_at.desc,id');S.passwordRequestsReady=true;}catch(err){S.passwordRequestsError=err.message;}}
function cashierPasswordRequestActive(q){return q.status==='Pending'||q.status==='Approved'&&new Date(q.approval_expires_at).getTime()>Date.now();}
function cashierPasswordRequestRows(){return (S.passwordRequests||[]).filter(q=>S.role==='BC'?q.user_id===S.session?.user?.id:canReadBranch(q.branch_id)&&inOperatingScope(q.branch_id));}
function cashierPasswordCount(){return cashierPasswordRequestRows().filter(q=>S.role==='BM'?q.status==='Pending':S.role==='BC'?q.status==='Approved'&&cashierPasswordRequestActive(q):false).length;}
function cashierPasswordNotificationMarkup(){if(!['BM','BC'].includes(S.role))return '';const count=cashierPasswordCount();return `<button type="button" class="outline small" onclick="go('Password requests')" aria-label="Cashier password requests: ${count} awaiting action">${icon('shield')}<span class="portal-count ${count?'has-pending':''}">${count}</span></button>`;}
function cashierPasswordRequestDialog(purpose){if(S.role!=='BC')return;openModal(purpose,`<form onsubmit="event.preventDefault();submitCashierPasswordRequest(this,'${purpose}')"><label>Reason / Comments / Notes<textarea name="reason" minlength="3" maxlength="2000" required placeholder="Explain why you need to change or recover your password. Do not include any password or PIN."></textarea></label><p class="hint">Your assigned BM will review this request. Your password remains unchanged until approval.</p><button class="primary" type="submit">Send to BM</button></form>`);}
async function submitCashierPasswordRequest(form,purpose){const btn=form.querySelector('[type=submit]');if(form.dataset.saving==='true')return;form.dataset.saving='true';btn.disabled=true;try{const reason=new FormData(form).get('reason');await rpc('occci_request_cashier_password',{purpose,reason});closeModal();await refreshCashierPasswordRequests();toast('Request sent to your Branch Manager.');}catch(err){$('actionMessage').textContent=err.message;}finally{form.dataset.saving='false';btn.disabled=false;}}
async function refreshCashierPasswordRequests(){if(typeof refreshAfterWrite==='function'&&typeof OCCCIRealtimeSDK!=='undefined')await refreshAfterWrite();else{await loadCashierPasswordRequests();render();}}
function cashierPasswordRequestsView(){return heading(S.role==='BC'?'My password requests':'Cashier password requests','The assigned Branch Manager approves or rejects each request.')+cashierPasswordRequestList();}
function cashierPasswordRequestList(){if(!S.passwordRequestsReady)return `<section class="card"><p class="form-error">${e(S.passwordRequestsError||'Password requests need database activation.')}</p>${button('Retry','refreshCashierPasswordRequests()','outline','switch')}</section>`;const rows=cashierPasswordRequestRows();return `<section class="card"><ul class="request-list">${rows.map(q=>{const p=S.profiles.find(p=>p.id===q.user_id),expired=q.status==='Approved'&&!cashierPasswordRequestActive(q);return `<li class="request-list-row"><div class="request-list-info"><div class="request-list-title"><h2>${e(p?staffIdentityLabel(p):'Branch Cashier')}</h2>${statusPill(expired?'Expired':q.status)}</div><p class="request-list-meta">${e(q.purpose)} · ${e(bn(q.branch_id))} · ${e(new Date(q.created_at).toLocaleString())}</p><p class="activity-note">${e(q.reason)}</p>${q.review_note?`<p class="smalltext">BM decision: ${e(q.review_note)}</p>`:''}${q.status==='Approved'&&!expired?`<p class="hint">Use once before ${e(new Date(q.approval_expires_at).toLocaleString())}.</p>`:''}</div><div class="flex">${S.role==='BM'&&q.status==='Pending'?button('Review',`cashierPasswordReviewDialog('${q.id}')`,'outline','shield'):''}${S.role==='BC'&&q.status==='Approved'&&!expired?button(q.purpose==='Recover password'?'Send recovery email':'Change password',q.purpose==='Recover password'?`sendCashierRecoveryEmail('${q.id}',this)`:`cashierNewPasswordDialog('${q.id}')`,'primary','shield'):''}</div></li>`;}).join('')}</ul>${rows.length?'':empty('No password requests','Submitted requests and BM decisions will appear here.')}</section>`;}
function cashierPasswordReviewDialog(id){const q=S.passwordRequests.find(q=>q.id===id);if(!q||S.role!=='BM'||!canReadBranch(q.branch_id)||q.status!=='Pending')return;openModal('Review cashier password request',`<p class="smalltext"><strong>${e(S.profiles.find(p=>p.id===q.user_id)?staffIdentityLabel(S.profiles.find(p=>p.id===q.user_id)):'Branch Cashier')}</strong> · ${e(q.purpose)} · ${e(bn(q.branch_id))}</p><p class="activity-note">${e(q.reason)}</p><form onsubmit="event.preventDefault();reviewCashierPassword(this,'${id}')"><label>Decision<select name="decision"><option>Approve</option><option>Reject</option></select></label><label>Reason / Comments / Notes<textarea name="note" minlength="3" maxlength="2000" required></textarea></label><button class="primary" type="submit">Save decision</button></form>`);}
async function reviewCashierPassword(form,id){const btn=form.querySelector('[type=submit]');if(form.dataset.saving==='true')return;form.dataset.saving='true';btn.disabled=true;try{const f=new FormData(form);await rpc('occci_review_cashier_password',{request_id:id,decision:f.get('decision'),note:f.get('note')});closeModal();await refreshCashierPasswordRequests();toast('BM decision recorded. The cashier has been notified.');}catch(err){$('actionMessage').textContent=err.message;}finally{form.dataset.saving='false';btn.disabled=false;}}
function approvedCashierPasswordRequest(id){const q=S.passwordRequests.find(q=>q.id===id);if(S.role!=='BC'||!q||q.user_id!==S.session?.user?.id||q.branch_id!==S.assignment?.branch_id||q.status!=='Approved'||!cashierPasswordRequestActive(q))throw Error('A current approval from your assigned BM is required.');return q;}
async function sendCashierRecoveryEmail(id,btn){btn.disabled=true;try{approvedCashierPasswordRequest(id);const email=S.session.user.email;if(!email)throw Error('This account needs a registered email address.');const redirect=location.origin+'/?cashierRecovery='+encodeURIComponent(id);await api('/auth/v1/recover?redirect_to='+encodeURIComponent(redirect),{method:'POST',auth:false,data:{email}});toast('Recovery email requested. Open the link sent to your registered email.');}catch(err){toast(err.message);}finally{btn.disabled=false;}}
function cashierNewPasswordDialog(id,recovery=false){try{const q=approvedCashierPasswordRequest(id);if(q.purpose==='Recover password'&&!recovery)throw Error('Open the recovery link from your registered email first.');openModal('Set a new password',`<form onsubmit="event.preventDefault();saveCashierPassword(this,'${id}',${recovery})"><div class="form-grid">${recovery?'':`<label class="full">Current account password<input type="password" name="current_password" autocomplete="current-password" required></label>`}<label>New password<input type="password" name="new_password" minlength="8" maxlength="72" autocomplete="new-password" required></label><label>Confirm new password<input type="password" name="confirm_password" minlength="8" maxlength="72" autocomplete="new-password" required></label></div><p class="hint">This uses your BM approval once. Sign in again with the new password afterward.</p><button class="primary" type="submit">Save new password</button></form>`);}catch(err){toast(err.message);}}
async function saveCashierPassword(form,id,recovery){const btn=form.querySelector('[type=submit]');if(form.dataset.saving==='true')return;form.dataset.saving='true';btn.disabled=true;let fresh=null;try{approvedCashierPasswordRequest(id);const f=new FormData(form),password=String(f.get('new_password')||''),userId=S.session.user.id;if(password.length<8||password.length>72||password!==f.get('confirm_password'))throw Error('Enter matching passwords with 8–72 characters.');if(recovery){if(S.cashierRecoveryId!==id)throw Error('Open your recovery email link first.');await api('/auth/v1/user',{method:'PUT',data:{password}});}else{try{fresh=await api('/auth/v1/token?grant_type=password',{method:'POST',auth:false,data:{email:S.session.user.email,password:f.get('current_password')}});}catch{throw Error('Current password confirmation failed.');}if(!fresh?.access_token||fresh.user?.id!==userId||S.session?.user?.id!==userId)throw Error('Confirm the signed-in cashier account.');await api('/auth/v1/user',{method:'PUT',auth:false,headers:{Authorization:'Bearer '+fresh.access_token},data:{password}});}S.cashierRecoveryId=null;closeModal();await signOut();toast('Password updated. Sign in with your new password.');}catch(err){$('actionMessage').textContent=err.message;}finally{for(const name of ['new_password','confirm_password','current_password'])if(form.elements[name])form.elements[name].value='';form.dataset.saving='false';btn.disabled=false;if(fresh?.access_token)try{await api('/auth/v1/logout?scope=local',{method:'POST',auth:false,headers:{Authorization:'Bearer '+fresh.access_token}});}catch{}}}
async function finishCashierRecovery(){const url=new URL(location.href),id=url.searchParams.get('cashierRecovery');if(!id)return;const params=new URLSearchParams(url.hash.slice(1)),token=params.get('access_token'),refresh=params.get('refresh_token'),type=params.get('type');url.searchParams.delete('cashierRecovery');url.hash='';history.replaceState(null,'',url.pathname+url.search);if(type!=='recovery'||!token||!refresh)throw Error('Recovery link is invalid or expired. Request another email from Settings.');const user=await api('/auth/v1/user',{auth:false,headers:{Authorization:'Bearer '+token}});storeSession({access_token:token,refresh_token:refresh,user,expires_at:Date.now()/1000+Math.min(3600,Math.max(1,Number(params.get('expires_in'))||3600))});S.cashierRecoveryId=id;S.page='Settings';}
